interface OrderObserver {
    void update(Order order);
}

class OrderService {
    private final List<OrderObserver> observers = new ArrayList<>();

    public void addObserver(OrderObserver observer) {
        observers.add(observer);
    }

    public void removeObserver(OrderObserver observer) {
        observers.remove(observer);
    }

    public void updateOrderStatus(Order order, OrderStatus newStatus) {
        order.setStatus(newStatus);
        notifyObservers(order);  // notify all registered observers
    }

    private void notifyObservers(Order order) {
        for (OrderObserver observer : observers) {
            observer.update(order);  // each observer reacts independently
        }
    }
}

class EmailNotificationObserver implements OrderObserver {
    public void update(Order order) {
        System.out.println("Sending email for order: " + order.getId());
    }
}

class InventoryObserver implements OrderObserver {
    public void update(Order order) {
        if (order.getStatus() == OrderStatus.CONFIRMED) {
            System.out.println("Reserving inventory for: " + order.getId());
        }
    }
}

@Service
class OrderService {
    private final ApplicationEventPublisher publisher;  // Spring's subject

    public OrderService(ApplicationEventPublisher publisher) {
        this.publisher = publisher;
    }

    public void confirmOrder(Long orderId) {
        var order = findOrder(orderId);
        order.setStatus(OrderStatus.CONFIRMED);
        publisher.publishEvent(new OrderConfirmedEvent(order));  // notify observers
    }
}

record OrderConfirmedEvent(Order order) {}

@Component
class EmailNotificationListener {
    @EventListener  // observer registration via annotation
    public void handleOrderConfirmed(OrderConfirmedEvent event) {
        System.out.println("Sending confirmation email for: " + event.order().getId());
    }
}

@Component
class InventoryListener {
    @EventListener
    public void handleOrderConfirmed(OrderConfirmedEvent event) {
        System.out.println("Reserving inventory for: " + event.order().getId());
    }
}

interface Observer {
    void update(String message);
}

interface Subject {
    void attach(Observer observer);
    void detach(Observer observer);
    void notifyObservers();
}

class NewsAgency implements Subject {
    private final List<Observer> observers = new ArrayList<>();
    private String news;

    public void attach(Observer observer) {
        observers.add(observer);
    }

    public void detach(Observer observer) {
        observers.remove(observer);
    }

    public void setNews(String news) {
        this.news = news;
        notifyObservers();  // trigger notification on state change
    }

    public void notifyObservers() {
        var snapshot = new ArrayList<>(observers);  // prevent ConcurrentModificationException
        for (Observer observer : snapshot) {
            observer.update(news);
        }
    }
}

class NewsChannel implements Observer {
    private final String channelName;

    public NewsChannel(String channelName) {
        this.channelName = channelName;
    }

    public void update(String news) {
        System.out.println(channelName + " received: " + news);
    }
}

record OrderPlacedEvent(Long orderId, BigDecimal total) {}

@Service
class OrderService {
    private final ApplicationEventPublisher eventPublisher;  // subject
    private final OrderRepository orderRepository;

    public OrderService(ApplicationEventPublisher eventPublisher, OrderRepository orderRepository) {
        this.eventPublisher = eventPublisher;
        this.orderRepository = orderRepository;
    }

    @Transactional
    public Order placeOrder(OrderRequest request) {
        var order = orderRepository.save(new Order(request));
        eventPublisher.publishEvent(new OrderPlacedEvent(order.getId(), order.getTotal()));
        return order;  // observers notified after this method completes
    }
}

@Component
class PaymentListener {  // observer 1
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void handleOrderPlaced(OrderPlacedEvent event) {
        System.out.println("Processing payment for order: " + event.orderId());
    }
}

@Component
class EmailListener {  // observer 2
    @EventListener  // fires immediately, no transaction awareness
    public void handleOrderPlaced(OrderPlacedEvent event) {
        System.out.println("Sending confirmation email for: " + event.orderId());
    }
}

class Subject {
    private final List<Observer> observers = new ArrayList<>();  // strong references

    public void attach(Observer observer) {
        observers.add(observer);
    }

    public void detach(Observer observer) {
        observers.remove(observer);  // often forgotten, causing memory leaks
    }
}

class Controller {
    public void createView() {
        var view = new HeavyView();  // large object with resources
        subject.attach(view::update);  // registers as observer
        // Problem: if view goes out of scope but isn't detached,
        // subject still holds a reference, preventing garbage collection
    }
}

// Solution: use weak references for automatic cleanup
class SafeSubject {
    private final List<WeakReference<Observer>> observers = new ArrayList<>();

    public void notifyObservers() {
        observers.removeIf(ref -> ref.get() == null);  // remove dead references
        for (var ref : observers) {
            var observer = ref.get();
            if (observer != null) {
                observer.update();
            }
        }
    }
}

class ThreadSafeSubject {
    private final List<Observer> observers = new CopyOnWriteArrayList<>();  // thread-safe for read-heavy

    public void attach(Observer observer) {
        observers.add(observer);  // safe concurrent add, creates new internal copy
    }

    public void detach(Observer observer) {
        observers.remove(observer);  // safe concurrent remove
    }

    public void notifyObservers(String message) {
        // Iteration is safe even if another thread modifies observers concurrently
        for (Observer observer : observers) {  // iterates over stable snapshot
            observer.update(message);
        }
    }
}

// Alternative: manual snapshot for ArrayList
class ManualSnapshotSubject {
    private final List<Observer> observers = new ArrayList<>();

    public synchronized void attach(Observer observer) {
        observers.add(observer);  // synchronize writes
    }

    public void notifyObservers(String message) {
        List<Observer> snapshot;
        synchronized (this) {
            snapshot = new ArrayList<>(observers);  // create snapshot under lock
        }
        for (Observer observer : snapshot) {  // iterate outside lock
            observer.update(message);
        }
    }
}
